    private final AtomicReference<Object> registryMonitor=new AtomicReference<>();
    @Test void concurrentFreeSpaceReservationStaysOwnedUntilFailedWriterReturns()throws Exception {
        var d=definition();var other=new JobDefinition(UUID.randomUUID(),d.fence(),group,d.columns(),d.capture(),d.limits());long reserve=d.limits().chunk().maximumFileBytes();var entered=new CountDownLatch(1);var resume=new CountDownLatch(1);var count=new AtomicInteger();var fail=new AtomicBoolean(true);
        var builder=new RatisExportSourceRegistry.NativeBuilder(){public boolean tokenUsable(JobDefinition ignored){return true;}public NativeRangeSstExport.Chunk build(JobDefinition def,RatisExportJournal.ChunkIntent intent,Path file,RatisExportSourceRegistry.Completion done)throws Exception{count.incrementAndGet();if(fail.get()){Files.write(file,new byte[]{1,2,3});entered.countDown();if(!resume.await(5,TimeUnit.SECONDS))throw new IOException("Timed out");throw new IOException("Writer failed after file creation");}var result=empty(def,intent);done.persist(result);return result;}};
        var limits=new RatisExportSourceService.IoLimits(100,1,MAX_READ_BYTES);
        try(var registry=new RatisExportSourceRegistry(root,RatisExportSourceRegistry.Budgets.defaults(),limits,builder,SessionJournalFiles.FILESYSTEM,path->reserve+100)){
            var actual=CompletableFuture.runAsync(()->{try{registry.build(request(d));}catch(Exception failure){throw new CompletionException(failure);}});
            try{assertTrue(entered.await(5,TimeUnit.SECONDS));assertThrows(IOException.class,()->registry.build(request(other)));assertFalse(Files.exists(root.resolve(other.jobId()+"-"+group).resolve("0.intent")));assertEquals(1,count.get());assertThrows(IOException.class,registry::close);resume.countDown();assertThrows(ExecutionException.class,()->actual.get(5,TimeUnit.SECONDS));fail.set(false);assertEquals(0,registry.build(request(other)).rows());var disk=RatisExportSourceRegistry.class.getDeclaredField("disk");disk.setAccessible(true);assertEquals(3,disk.getLong(registry),"Failed artifact remains charged after native reservation refund");}finally{resume.countDown();actual.handle((value,failure)->null).get(5,TimeUnit.SECONDS);}
        }
    }
    static final class FakeWakeup implements RatisExportSourceService.Wakeup {
        Runnable pending;long delay;int maximumPending;boolean closed;
        public synchronized Runnable schedule(Runnable task,long delay){assertNull(pending);pending=task;this.delay=delay;maximumPending=Math.max(maximumPending,1);return ()->{synchronized(this){if(pending==task)pending=null;}};}
        void fire(){Runnable task;synchronized(this){task=pending;pending=null;}assertNotNull(task);task.run();}
        public synchronized void close(){closed=true;assertNull(pending);}
    }
    @Test void rateWaitCoalescesViewsChargesRetryAndReleaseFencesQueuedRequest()throws Exception {
        var d=definition();var clock=new AtomicLong();var wakeup=new FakeWakeup();var scheduler=it.cavallium.rockserver.core.impl.RWScheduler.forTesting(1,1,1,8,8,"source-rate");var limits=new RatisExportSourceService.IoLimits(0,MAX_READ_BYTES,MAX_READ_BYTES);
        var builder=new RatisExportSourceRegistry.NativeBuilder(){public boolean tokenUsable(JobDefinition ignored){return true;}public NativeRangeSstExport.Chunk build(JobDefinition def,RatisExportJournal.ChunkIntent intent,Path file,RatisExportSourceRegistry.Completion done)throws Exception{var result=artifact(def,intent,file,null,false);done.persist(result);return result;}};
        var registry=new RatisExportSourceRegistry(root,RatisExportSourceRegistry.Budgets.defaults(),limits,builder);var desc=registry.build(request(d));var service=new RatisExportSourceService(registry,RatisExportSourceRegistry.Budgets.defaults(),limits,scheduler,clock::get,wakeup);byte[] read=new ReadRequest(d,0,desc.digest(),0,MAX_READ_BYTES).encode();
        try{
            assertArrayEquals(new byte[]{1,2,3},ReadReply.decode(service.submit(group,RatisExportSourceService.READ,read).get(5,TimeUnit.SECONDS)).bytes());
            var retry=service.submit(group,RatisExportSourceService.READ,read);var coalesced=service.submit(group,RatisExportSourceService.READ,read);assertFalse(retry.isDone());assertFalse(coalesced.isDone());synchronized(wakeup){assertEquals(1_000_000_000L,wakeup.delay);assertNotNull(wakeup.pending);}
            synchronized(service){clock.set(999_999_999L);wakeup.fire();}assertFalse(retry.isDone());synchronized(wakeup){assertEquals(1,wakeup.delay);}synchronized(service){clock.incrementAndGet();wakeup.fire();}assertArrayEquals(retry.get(5,TimeUnit.SECONDS),coalesced.get(5,TimeUnit.SECONDS));
            var queued=service.submit(group,RatisExportSourceService.READ,read);var work=RatisExportSourceService.class.getDeclaredField("work");work.setAccessible(true);Object retained;synchronized(service){retained=((Map<?,?>)work.get(service)).values().iterator().next();}var decoded=retained.getClass().getDeclaredField("request");decoded.setAccessible(true);assertNotNull(decoded.get(retained));
            assertTrue(queued.cancel(false));ReleaseReply.decode(service.submit(group,RatisExportSourceService.RELEASE,new ReleaseRequest(d).encode()).get(5,TimeUnit.SECONDS));assertNull(decoded.get(retained));service.stop().get(5,TimeUnit.SECONDS);assertTrue(wakeup.closed);assertEquals(1,wakeup.maximumPending);
        }finally{service.stop().get(5,TimeUnit.SECONDS);scheduler.disposeGracefully().block(java.time.Duration.ofSeconds(5));}
    }
